function draw() {
  background("#f1e9df");
	
	strokeWeight(1);
	
	if (drawEdges) {
		stroke(25);
	} else {
		noStroke();
	}
	
	lights();
	
	fill(255);
	textAlign(CENTER);
// Instructions moved into the HTML UI.

	push();
	translate(0, 50);
	scale(min(100,width*.24));
	rotateX(radians(180));
	rotateY(radians(160));
	
	blendMeshToTargets();
	
	for (let blendMesh of Object.values(blendMeshes)) {
		blendMesh.refreshMesh();
	}
	
	displayMeshes();
	pop();
	
	for (let control of controls) {
		control.slideControl();
		if (drawControls) {
			control.display();
		}
	}
}

function displayMeshes() {
	ambientLight(50);
	directionalLight(80, 80, 80, -0.6, 0.55, -1);
	directionalLight(180,180,170,.2,-.48,.5);
	
	ambientMaterial(R.palette%2?170:225,R.palette%2?125:215,R.palette%2?80:200);
  model(blendMeshes.normal.mesh);
	
	ambientMaterial(75, 60, 50);
	model(blendMeshes.brows.mesh);
	model(meshes.hair);
	
	ambientMaterial(255, 255, 255);
	model(meshes.eyes);
	
	ambientMaterial(155, 208, 235);
	model(meshes.iris);
	
	ambientMaterial(0, 0, 0);
	model(meshes.pupils);
}

// Maps the verts to their targets based on the controls' offset.
function blendMeshToTargets() {
	for (let control of controls) {
		control.storeOutputs();
	}
	
	for (let blendMesh of Object.values(blendMeshes)) {
		for (let vertIndex = 0; vertIndex < blendMesh.mesh.vertices.length; vertIndex++) {
			// Reset vert to default pose.
			blendMesh.resetPoint(vertIndex);

			// Add on all deltas to verts.
			for (let control of controls) {
				for (let targetGroup of control.targetGroups) {
					if (blendMesh.mesh == targetGroup.blendMesh.mesh) {
						if (targetGroup.yawTarget != null) {
							targetGroup.blendMesh.addDelta(targetGroup.yawTarget, control.outputs.x, vertIndex);
						}

						if (targetGroup.pitchTarget != null) {
							targetGroup.blendMesh.addDelta(targetGroup.pitchTarget, control.outputs.y, vertIndex);
						}
					}
				}
			}
		}
	}
}

function keyPressed() {
	if (key == ' ') {
		drawEdges = !drawEdges;
	} else {
		drawControls = !drawControls;
	}
}

function activateFaceControl() {
	// Activate control the mouse is hovering over.
	for (let control of controls) {
		if (control.isHoverOver()) {
			control.active = true;
			break;
		}
	}
}

function releaseFaceControl() {
	for (let control of controls) {
		control.active = false;
	}
}

// Original tab: targetGroup.js
// Identifies targets that the blend mesh can lerp to.
function TargetGroup(_blendMesh, _upTarget, _downTarget, _leftTarget, _rightTarget) {
	this.blendMesh = _blendMesh;
	this.upTarget = _upTarget;
	this.downTarget = _downTarget;
	this.leftTarget = _leftTarget;
	this.rightTarget = _rightTarget;
	this.yawTarget = null;
	this.pitchTarget = null;
}

// Touch and UI adaptation; original visual algorithm above.
